import { test, expect } from '@playwright/test';

test.describe('File Upload Progress Bar', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/file-upload');
  });

  test('should display progress bar for each uploaded file', async ({ page }) => {
    // Locate and click the file input using getByLabel
    const fileInput = page.getByLabel('Select files');
    await fileInput.setInputFiles('test-file.pdf');

    // Verify file name appears
    const fileNameDisplay = page.getByText('test-file.pdf');
    await expect(fileNameDisplay).toBeVisible();

    // Verify progress bar container is visible
    const progressBarContainer = page.getByRole('region', { name: /file upload progress/i });
    await expect(progressBarContainer).toBeVisible();

    // Verify progress bar exists for the file
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify progress text is displayed
    const progressText = page.getByText(/0%/);
    await expect(progressText).toBeVisible();

    // Verify progress bar has a value
    const progressValue = page.getByText(/00%/);
    await expect(progressValue).toBeVisible();

    // Click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for progress to update
    await page.waitForTimeout(1000);

    // Verify progress bar has updated
    await expect(progressBar).toHaveAttribute('aria-valuenow', '50');
    await expect(progressText).toContainText('50%');
    await expect(progressValue).toContainText('50%');
  });

  test('should handle multiple files and display progress for each', async ({ page }) => {
    // Locate and click the file input using getByLabel
    const fileInput = page.getByLabel('Select files');
    await fileInput.setInputFiles('doc1.pdf', 'image.png');

    // Verify both file names appear
    const fileName1 = page.getByText('doc1.pdf');
    const fileName2 = page.getByText('image.png');
    await expect(fileName1).toBeVisible();
    await expect(fileName2).toBeVisible();

    // Verify progress bar container is visible
    const progressBarContainer = page.getByRole('region', { name: /file upload progress/i });
    await expect(progressBarContainer).toBeVisible();

    // Click upload button using getByRole
    const uploadButton = page.getByRole('button', { name: /upload/i });
    await uploadButton.click();

    // Wait for progress to update
    await page.waitForTimeout(1500);

    // Verify progress bar for doc1.pdf has updated
    const progressBarDoc1 = page.getByRole('progressbar', { name: /doc1\.pdf/i });
    await expect(progressBarDoc1).toBeVisible();
    await expect(progressBarDoc1).toHaveAttribute('aria-valuenow', '75');

    // Verify progress text for doc1.pdf is displayed
    const progressTextDoc1 = page.getByText(/75%/);
    await expect(progressTextDoc1).toBeVisible();

    // Verify progress bar for image.png has updated
    const progressBarImage = page.getByRole('progressbar', { name: /image\.png/i });
    await expect(progressBarImage).toBeVisible();
    await expect(progressBarImage).toHaveAttribute('aria-valuenow', '25');

    // Verify progress text for image.png is displayed
    const progressTextImage = page.getByText(/25%/);
    await expect(progressTextImage).toBeVisible();
  });
});
